#include <bits/stdc++.h>
using namespace std;

int maxPowerLimit, baseNumber;
unordered_set<long long> sumSet;

void generateAllSums(int index, long long currentSum, int maxExp, int baseVal) {
    if (index > maxExp) {
        sumSet.insert(currentSum);
        return;
    }
    long long powerVal = 1;
    for (int i = 0; i < index; ++i) {
        powerVal *= baseVal;
        if (powerVal > 1e9) break;
    }
    generateAllSums(index + 1, currentSum + powerVal, maxExp, baseVal);
    generateAllSums(index + 1, currentSum, maxExp, baseVal);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int baseVal;
    long long targetVal;
    cin >> baseVal >> targetVal;

    int maxPower = 0;
    for (int i = 0; baseVal > 2 && i < 21; i++) {
        if (pow(baseVal, i) > 1e9) break;
        maxPower = i;
    }

    sumSet.clear();
    if (baseVal > 2) generateAllSums(0, 0, maxPower, baseVal);

    bool canForm = false;
    if (baseVal == 2) canForm = true;

    for (auto sumVal : sumSet) {
        if (sumVal >= targetVal && sumSet.count(sumVal - targetVal)) {
            canForm = true;
            break;
        }
    }

    cout << (canForm ? "YES" : "NO") << "\n";

    return 0;
}
